-- End-to-end authorization and state-machine checks; every fixture is rolled back.
begin;
do $$
declare a uuid=gen_random_uuid(); b uuid=gen_random_uuid(); u uuid=gen_random_uuid(); w uuid; sid uuid; foreign_sid uuid; c uuid; h uuid; job uuid; ind uuid; failed boolean;
begin
 insert into auth.users(id,email,email_confirmed_at,aud,role) values(a,a||'@example.invalid',now(),'authenticated','authenticated'),(b,b||'@example.invalid',now(),'authenticated','authenticated'),(u,u||'@example.invalid',now(),'authenticated','authenticated');
 perform set_config('request.jwt.claim.sub',a::text,true); execute 'set local role authenticated';
 w=(public.command('join','{"intent":"create_workspace","name":"Operations QA","person":"Owner A"}')->>'id')::uuid;
 sid=(public.command('station','{"name":"QA station","omc":"QA","city":"Karachi"}')->>'id')::uuid;
 perform public.command('invite',jsonb_build_object('station_id',sid,'email',u||'@example.invalid','name','Supervisor'));
 perform set_config('request.jwt.claim.sub',u::text,true); perform public.command('accept_invite',jsonb_build_object('invitation_id',public.onboarding()->'invitations'->0->>'id'));
 perform set_config('request.jwt.claim.sub',a::text,true);
 c=(public.ops_command('create',jsonb_build_object('station_id',sid,'kind','exception','title','Investigate discrepancy'))->>'id')::uuid;
 failed=false;begin perform public.ops_command('transition',jsonb_build_object('id',c,'expected_status','open','status','resolved','note','Skipped investigation'));exception when others then failed=true;end;assert failed,'Case skipped investigation';
 perform public.ops_command('transition',jsonb_build_object('id',c,'expected_status','open','status','investigating'));
 failed=false;begin perform public.ops_command('transition',jsonb_build_object('id',c,'expected_status','investigating','status','resolved'));exception when others then failed=true;end;assert failed,'Case resolved without a decision';
 perform public.ops_command('transition',jsonb_build_object('id',c,'expected_status','investigating','status','resolved','note','Rechecked physical readings and documented the cause'));
 failed=false;begin perform public.ops_command('transition',jsonb_build_object('id',c,'expected_status','resolved','status','open'));exception when others then failed=true;end;assert failed,'Closed case reopened';
 h=(public.ops_command('create',jsonb_build_object('station_id',sid,'kind','handover','title','Accept the briefing','assigned_to',u))->>'id')::uuid;
 failed=false;begin perform public.ops_command('transition',jsonb_build_object('id',h,'expected_status','pending','status','accepted'));exception when others then failed=true;end;assert failed,'Sender accepted their own handover';
 failed=false;begin perform public.ops_command('create',jsonb_build_object('station_id',sid,'kind','handover','title','Invalid self handover','assigned_to',a));exception when others then failed=true;end;assert failed,'Self handover created';
 ind=(public.ops_command('create',jsonb_build_object('station_id',sid,'kind','indent','title','Request MS supply','supplier','OMC QA','grade','MS','liters',10000,'assigned_to',u))->>'id')::uuid;
 failed=false;begin perform public.ops_command('transition',jsonb_build_object('id',ind,'expected_status','requested','status','received'));exception when others then failed=true;end;assert failed,'Indent skipped approval';
 perform public.ops_command('transition',jsonb_build_object('id',ind,'expected_status','requested','status','approved'));
 failed=false;begin perform public.ops_command('transition',jsonb_build_object('id',ind,'expected_status','approved','status','dispatched'));exception when others then failed=true;end;assert failed,'Dispatched without actual delivery';
 job=(public.ops_command('create',jsonb_build_object('station_id',sid,'kind','maintenance','title','Service dispenser','assigned_to',u,'equipment','N1'))->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',u::text,true);
 assert (select count(*) from public.station_work_items where id=c)=0,'Supervisor can read owner case';
 assert not exists(select 1 from jsonb_array_elements(public.ops_snapshot(sid)->'items') x where x->>'id'=c::text),'Snapshot leaked owner case';
 failed=false;begin perform public.ops_command('create',jsonb_build_object('station_id',sid,'kind','indent','title','Unauthorized fuel indent','supplier','QA','grade','MS','liters',1));exception when others then failed=true;end;assert failed,'Supervisor created an indent';
 failed=false;begin perform public.ops_command('transition',jsonb_build_object('id',ind,'expected_status','approved','status','cancelled','note','Unauthorized cancellation'));exception when others then failed=true;end;assert failed,'Supervisor cancelled indent';
 perform public.ops_command('transition',jsonb_build_object('id',h,'expected_status','pending','status','accepted'));
 perform public.ops_command('transition',jsonb_build_object('id',job,'expected_status','scheduled','status','in_progress'));
 failed=false;begin perform public.ops_command('transition',jsonb_build_object('id',job,'expected_status','scheduled','status','completed','note','Stale request'));exception when others then failed=true;end;assert failed,'Stale state accepted';
 failed=false;begin perform public.ops_command('transition',jsonb_build_object('id',job,'expected_status','in_progress','status','completed'));exception when others then failed=true;end;assert failed,'Maintenance completed without note';
 perform public.ops_command('transition',jsonb_build_object('id',job,'expected_status','in_progress','status','completed','note','Replaced seal and checked the dispenser'));
 failed=false;begin update public.station_work_items set title='Bypassed workflow' where id=job;exception when insufficient_privilege then failed=true;end;assert failed,'Direct write permitted';
 failed=false;begin delete from public.work_item_events where item_id=job;exception when insufficient_privilege then failed=true;end;assert failed,'History deletion permitted';
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.command('join','{"intent":"create_workspace","name":"Other workspace","person":"Owner B"}');
 foreign_sid=(public.command('station','{"name":"Foreign station","omc":"QA","city":"Karachi"}')->>'id')::uuid;
 assert (select count(*) from public.station_work_items where station_id=sid)=0,'Cross tenant read';
 failed=false;begin perform public.ops_snapshot(sid);exception when others then failed=true;end;assert failed,'Cross tenant snapshot';
 failed=false;begin perform public.ops_command('comment',jsonb_build_object('id',job,'note','Cross tenant comment'));exception when others then failed=true;end;assert failed,'Cross tenant mutation';
 perform set_config('request.jwt.claim.sub',a::text,true);
 failed=false;begin perform public.ops_command('create',jsonb_build_object('station_id',sid,'kind','maintenance','title','Foreign assignee','assigned_to',b));exception when others then failed=true;end;assert failed,'Foreign assignee accepted';
 execute 'reset role';update public.memberships set active=false where user_id=u;execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',u::text,true);
 failed=false;begin perform public.ops_snapshot(sid);exception when others then failed=true;end;assert failed,'Revoked member retained access';
 execute 'set local role anon';
 failed=false;begin perform public.ops_snapshot(sid);exception when insufficient_privilege then failed=true;end;assert failed,'Anonymous access permitted';
 execute 'reset role';
end $$;
select 'station operations checks passed; fixtures rolled back' result;
rollback;
